-- =====================================================================
-- 05_itam_seed.sql : MADE-UP sample data for the IT asset tracker.
-- Generated by scripts/generate-seed.mjs from scripts/itam-seed-data.mjs.
-- Do not edit by hand; change the script and run  npm run seed:generate
--
-- Every person, email (example.com), serial number, invoice and price is
-- invented. Dates are written as  current_date - N  so the data always
-- looks recent.
-- =====================================================================

begin;
truncate itam.license_seats, itam.licenses, itam.device_checks, itam.asset_events,
         itam.assets, itam.models, itam.employees, itam.locations;









-- Move each ID counter past the rows we inserted, so new rows get new IDs.
select setval(pg_get_serial_sequence('itam.locations', 'location_id'), (select coalesce(max(location_id), 0) + 1 from itam.locations), false);
select setval(pg_get_serial_sequence('itam.employees', 'employee_id'), (select coalesce(max(employee_id), 0) + 1 from itam.employees), false);
select setval(pg_get_serial_sequence('itam.models', 'model_id'), (select coalesce(max(model_id), 0) + 1 from itam.models), false);
select setval(pg_get_serial_sequence('itam.assets', 'asset_id'), (select coalesce(max(asset_id), 0) + 1 from itam.assets), false);
select setval(pg_get_serial_sequence('itam.asset_events', 'event_id'), (select coalesce(max(event_id), 0) + 1 from itam.asset_events), false);
select setval(pg_get_serial_sequence('itam.device_checks', 'check_id'), (select coalesce(max(check_id), 0) + 1 from itam.device_checks), false);
select setval(pg_get_serial_sequence('itam.licenses', 'license_id'), (select coalesce(max(license_id), 0) + 1 from itam.licenses), false);

commit;
